function balancedTrios(readings) {
  const v = [...readings].sort((x, y) => x - y)
  const out = []
  for (let i = 0; i < v.length - 2; i++) {
    if (v[i] > 0) break
    if (i > 0 && v[i] === v[i - 1]) continue
    let lo = i + 1
    let hi = v.length - 1
    while (lo < hi) {
      const sum = v[i] + v[lo] + v[hi]
      if (sum < 0) lo++
      else if (sum > 0) hi--
      else {
        out.push([v[i], v[lo], v[hi]])
        lo++
        hi--
        while (lo < hi && v[lo] === v[lo - 1]) lo++
        while (lo < hi && v[hi] === v[hi + 1]) hi--
      }
    }
  }
  return out
}

