def balanced_trios(readings):
    v = sorted(readings)
    out = []
    for i in range(len(v) - 2):
        if v[i] > 0:
            break
        if i > 0 and v[i] == v[i - 1]:
            continue
        lo, hi = i + 1, len(v) - 1
        while lo < hi:
            total = v[i] + v[lo] + v[hi]
            if total < 0:
                lo += 1
            elif total > 0:
                hi -= 1
            else:
                out.append([v[i], v[lo], v[hi]])
                lo += 1
                hi -= 1
                while lo < hi and v[lo] == v[lo - 1]:
                    lo += 1
                while lo < hi and v[hi] == v[hi + 1]:
                    hi -= 1
    return out
